const context = $("Set Backfill Range2").first().json;
const minScore = Number(context.min_keyword_score || 35);
const maxAiCandidates = Number(context.max_ai_candidates || 0);

const strongAnimalTerms = [
  "animal", "animals", "animal welfare", "animal health", "animal disease",
  "animal testing", "laboratory animal", "laboratory animals", "lab animal",
  "lab animals", "humane handling", "animal handling", "animal care",
  "animal cruelty", "livestock", "cattle", "calves", "swine", "pig", "pigs",
  "pork", "poultry", "chicken", "chickens", "turkey", "turkeys", "sheep",
  "goat", "goats", "horse", "horses", "equine", "veterinary", "veterinarian",
  "wildlife", "endangered species", "threatened species", "marine mammal",
  "marine mammals", "migratory bird", "migratory birds", "fish and wildlife",
  "fisheries", "habitat", "refuge", "national wildlife refuge",
  "habitat conservation", "critical habitat", "species status assessment",
  "animal and plant health inspection service", "aphis", "fish and wildlife service",
  "noaa fisheries", "national marine fisheries service", "food safety and inspection service",
  "fsis", "animal drugs", "new animal drug", "zoonotic", "zoonosis", "aquaculture",
  "slaughter", "meat inspection", "animal transport", "quarantine facilities",
  "primate", "primates", "dog", "dogs", "cat", "cats", "trapping", "hunting",
  "fishing regulations", "invasive species"
];

const strongAnimalAgencies = [
  "animal and plant health inspection service", "aphis",
  "food safety and inspection service", "fsis",
  "fish and wildlife service",
  "national marine fisheries service", "noaa fisheries",
  "national oceanic and atmospheric administration",
  "commerce department",
  "agriculture department", "u.s. department of agriculture",
  "interior department", "food and drug administration", "fda",
  "national institutes of health", "nih",
  "environmental protection agency", "epa"
];

const policyTerms = [
  "proposed rule", "final rule", "rule", "notice", "public comment", "comments",
  "comment period", "hearing", "permit", "authorization", "incidental take",
  "incidental harassment authorization", "endangered species act",
  "marine mammal protection act", "animal welfare act", "inspection", "quarantine",
  "import", "export", "disease", "management", "conservation", "habitat",
  "research", "monitoring", "compliance", "enforcement", "approval", "renewal"
];

const negativeTerms = [
  "federal reserve", "bank holding company", "securities and exchange",
  "stock exchange", "federal energy regulatory commission", "student aid",
  "department of education", "nuclear reactor", "tin mill", "steel",
  "countervailing duty", "antidumping", "anti-dumping", "tariff",
  "imports from china", "international trade commission", "citric acid",
  "citrate salts", "airworthiness directive", "airworthiness directives",
  "airbus", "boeing", "airplane", "airplanes", "aviation", "faa",
  "medical devices", "neurological devices", "radiological health"
];

function normalize(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function hasTerm(text, term) {
  const normalizedText = normalize(text);
  const normalizedTerm = normalize(term);
  if (!normalizedText || !normalizedTerm) return false;
  const pattern = new RegExp(`(^|\\W)${escapeRegex(normalizedTerm)}($|\\W)`, "i");
  return pattern.test(normalizedText);
}

function matchedTerms(text, terms) {
  return terms.filter(term => hasTerm(text, term));
}

const output = [];

for (const item of $input.all()) {
  const doc = item.json || {};

  const title = normalize(doc.title);
  const abstract = normalize(doc.abstract);
  const agency = normalize(doc.agency);
  const type = normalize(doc.document_type);
  const titleAndAbstract = [title, abstract].join(" ");
  const fullText = [title, abstract, agency, type].join(" ");

  const animalMatches = matchedTerms(titleAndAbstract, strongAnimalTerms);
  const agencyMatches = matchedTerms(agency, strongAnimalAgencies);
  const policyMatches = matchedTerms(fullText, policyTerms);
  const negativeMatches = matchedTerms(fullText, negativeTerms);

  let score = 0;

  for (const term of strongAnimalTerms) {
    if (hasTerm(title, term)) score += 50;
    if (hasTerm(abstract, term)) score += 30;
  }

  if (agencyMatches.length > 0) score += 25;
  if (policyMatches.length > 0) score += 15;
  if (doc.comment_url) score += 10;

  if (hasTerm(type, "proposed rule")) score += 15;
  else if (hasTerm(type, "rule")) score += 10;
  else if (hasTerm(type, "notice")) score += 5;

  if (negativeMatches.length > 0 && animalMatches.length === 0 && agencyMatches.length === 0) {
    score -= 100;
  }

  const hasAnimalSignal = animalMatches.length > 0 || agencyMatches.length > 0;
  const hasPolicySignal = policyMatches.length > 0 || doc.comment_url || type.includes("notice") || type.includes("rule");

  if (hasAnimalSignal && hasPolicySignal && score >= minScore) {
    output.push({
      json: {
        ...doc,
        strict_score: score,
        matched_terms: [...new Set(animalMatches)],
        matched_agencies: [...new Set(agencyMatches)],
        matched_policy_terms: [...new Set(policyMatches)],
        matched_negative_terms: [...new Set(negativeMatches)],
        filter_stage: "strict_animal_policy_candidate"
      }
    });
  }
}

output.sort((a, b) => (b.json.strict_score || 0) - (a.json.strict_score || 0));

if (maxAiCandidates > 0) {
  return output.slice(0, maxAiCandidates);
}

return output;

// Historical Federal Register animal-policy backfill.
// Goal:
// Fetch one-year Federal Register data -> strict candidate filter -> embeddings -> OpenRouter final relevance
// -> store ONLY final relevant animal-policy notices in public.fr_documents.
// Rejected records are NOT stored.

const start_date = "2025-01-01";
const end_date = new Date().toISOString().split("T")[0];

return [
  {
    json: {
      start_date,
      end_date,
      per_page: 1000,
      base_url: "https://www.federalregister.gov/api/v1/documents.json",
      lookup_mode: "historical_animal_backfill_strict_final_only",
      min_keyword_score: 35,
      min_embedding_similarity: 0.30,
      // 0 means no cap. For quick testing set this to 25 or 50.
      max_ai_candidates: 0,
      embedding_model: "openai/text-embedding-3-small",
      relevance_model: "openai/gpt-4o-mini"
    }
  }
];

const firstResponse = $input.first().json;
const context = $("Restore Backfill Context1").first().json;

const totalPages = Number(firstResponse.total_pages || 1);
// Full pagination. For a test run, temporarily set hardLimitPages = 2.
const hardLimitPages = totalPages;
const items = [];

for (let page = 1; page <= hardLimitPages; page++) {
  const pageUrl =
    context.base_url +
    "?per_page=" + context.per_page +
    "&page=" + page +
    "&order=newest" +
    "&conditions[publication_date][gte]=" + context.start_date +
    "&conditions[publication_date][lte]=" + context.end_date;

  items.push({
    json: {
      page,
      total_pages: totalPages,
      page_url: pageUrl,
      start_date: context.start_date,
      end_date: context.end_date,
      lookup_mode: context.lookup_mode,
      min_keyword_score: context.min_keyword_score,
      min_embedding_similarity: context.min_embedding_similarity,
      max_ai_candidates: context.max_ai_candidates,
      embedding_model: context.embedding_model,
      relevance_model: context.relevance_model
    }
  });
}

return items;

const pageItems = $input.all();
const output = [];

function ymd(value) {
  if (!value) return "";
  return String(value).slice(0, 10);
}

function agencyNames(doc) {
  if (!Array.isArray(doc.agencies)) return "";
  return doc.agencies
    .map(a => a.name || a.raw_name || "")
    .filter(Boolean)
    .join("; ");
}

function agencySlugs(doc) {
  if (!Array.isArray(doc.agencies)) return "";
  return doc.agencies
    .map(a => a.slug || "")
    .filter(Boolean)
    .join(";");
}

const context = $("Set Backfill Range2").first().json;

for (const pageItem of pageItems) {
  const response = pageItem.json || {};
  const docs = Array.isArray(response.results) ? response.results : [];

  for (const doc of docs) {
    const id = doc.document_number || doc.html_url || doc.pdf_url || doc.title;
    if (!id) continue;

    output.push({
      json: {
        id,
        document_number: doc.document_number || "",
        title: doc.title || "",
        abstract: doc.abstract || doc.excerpts || "",
        document_type: doc.type || doc.document_type || "",
        publication_date: ymd(doc.publication_date),
        agency: agencyNames(doc),
        agency_slugs: agencySlugs(doc),
        html_url: doc.html_url || "",
        pdf_url: doc.pdf_url || "",
        comment_url: doc.comment_url || "",
        lookup_mode: context.lookup_mode
      }
    });
  }
}

return output;

const context = $("Set Backfill Range2").first().json;

const referenceText = [
  "Federal Register policy, regulation, enforcement, public comment, permit, hearing, or agency notice that affects animals, animal welfare, animal health, wildlife, endangered species, threatened species, laboratory animals, livestock, veterinary medicine, humane handling, animal transport, slaughter, marine mammals, migratory birds, fisheries, habitat, conservation, animal disease, or animal advocacy.",
  "Relevant agencies include USDA APHIS, USDA FSIS, FDA Center for Veterinary Medicine, Fish and Wildlife Service, NOAA Fisheries, National Marine Fisheries Service, Interior Department, Agriculture Department."
].join(" ");

function cleanText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .replace(/[\u0000-\u001F\u007F]/g, " ")
    .trim();
}

return $input.all().map(item => {
  const doc = item.json || {};

  const docText = [
    `Title: ${cleanText(doc.title)}`,
    `Agency: ${cleanText(doc.agency)}`,
    `Type: ${cleanText(doc.document_type)}`,
    `Publication Date: ${cleanText(doc.publication_date)}`,
    `Abstract: ${cleanText(doc.abstract)}`,
    `Matched Animal Terms: ${Array.isArray(doc.matched_terms) ? doc.matched_terms.join(", ") : cleanText(doc.matched_terms)}`,
    `Matched Animal Agencies: ${Array.isArray(doc.matched_agencies) ? doc.matched_agencies.join(", ") : cleanText(doc.matched_agencies)}`,
    `Matched Policy Terms: ${Array.isArray(doc.matched_policy_terms) ? doc.matched_policy_terms.join(", ") : cleanText(doc.matched_policy_terms)}`
  ].join("\n").slice(0, 7000);

  return {
    json: {
      ...doc,
      embedding_input_text: docText,
      embedding_reference_text: referenceText,
      embedding_request_body: {
        model: context.embedding_model || "openai/text-embedding-3-small",
        input: [docText, referenceText]
      }
    }
  };
});

const context = $("Set Backfill Range2").first().json;
const minSimilarity = Number(context.min_embedding_similarity || 0.30);

function cosineSimilarity(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length || a.length === 0) return 0;
  let dot = 0;
  let normA = 0;
  let normB = 0;
  for (let i = 0; i < a.length; i++) {
    const x = Number(a[i] || 0);
    const y = Number(b[i] || 0);
    dot += x * y;
    normA += x * x;
    normB += y * y;
  }
  if (!normA || !normB) return 0;
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

function fallbackScore(doc) {
  const text = [
    doc.title,
    doc.abstract,
    doc.agency,
    doc.document_type,
    Array.isArray(doc.matched_terms) ? doc.matched_terms.join(" ") : doc.matched_terms,
    Array.isArray(doc.matched_agencies) ? doc.matched_agencies.join(" ") : doc.matched_agencies,
    Array.isArray(doc.matched_policy_terms) ? doc.matched_policy_terms.join(" ") : doc.matched_policy_terms
  ].join(" ").toLowerCase();

  const terms = [
    "animal welfare", "marine mammal", "marine mammals", "wildlife",
    "endangered species", "threatened species", "fish and wildlife",
    "laboratory animal", "livestock", "veterinary", "animal disease",
    "public comment", "comments", "permit", "authorization",
    "incidental take", "incidental harassment", "marine mammal protection act",
    "animal welfare act", "endangered species act"
  ];

  let score = 0;
  for (const term of terms) {
    if (text.includes(term)) score += 0.05;
  }
  return Math.min(score, 0.95);
}

const output = [];

for (const item of $input.all()) {
  const doc = item.json || {};
  const embeddingData = Array.isArray(doc.data) ? doc.data : [];

  const docEmbedding = embeddingData[0]?.embedding || [];
  const refEmbedding = embeddingData[1]?.embedding || [];

  let embeddingScore = 0;
  if (Array.isArray(docEmbedding) && docEmbedding.length > 0 && Array.isArray(refEmbedding) && refEmbedding.length > 0) {
    embeddingScore = cosineSimilarity(docEmbedding, refEmbedding);
  } else {
    embeddingScore = fallbackScore(doc);
  }

  const strictScore = Number(doc.strict_score || 0);

  // This is a candidate gate only. Final strict decision happens in OpenRouter.
  const passEmbedding =
    embeddingScore >= minSimilarity ||
    strictScore >= 60 ||
    String(doc.abstract || "").toLowerCase().includes("marine mammal") ||
    String(doc.abstract || "").toLowerCase().includes("endangered species") ||
    String(doc.abstract || "").toLowerCase().includes("wildlife");

  if (!passEmbedding) {
    continue;
  }

  output.push({
    json: {
      ...doc,
      embedding_score: Number(embeddingScore.toFixed(4)),
      embedding_gate_status: "PASSED"
    }
  });
}

return output;

const context = $("Set Backfill Range2").first().json;

return $input.all().map(item => {
  const doc = item.json || {};

  const prompt = `You are classifying U.S. Federal Register documents for an animal advocacy notification system.

Be strict. Approve only documents that clearly affect animals, animal welfare, animal health, wildlife, endangered species, laboratory animals, livestock, veterinary medicine, humane handling, animal transport, slaughter/meat inspection, marine mammals, migratory birds, fisheries, habitat, permits, public comments, hearings, rulemaking, or agency action affecting animals.

Reject weak matches, generic agency notices, finance, aviation, trade, education, banking, human medical devices, and unrelated government administration.

Return ONLY the exact field format below. No markdown.

Document:
Title: ${doc.title || ""}
Agency: ${doc.agency || ""}
Publication Date: ${doc.publication_date || ""}
Document Type: ${doc.document_type || ""}
Document Number: ${doc.document_number || ""}
Abstract: ${doc.abstract || ""}
Source URL: ${doc.html_url || ""}
PDF URL: ${doc.pdf_url || ""}
Comment URL: ${doc.comment_url || ""}
Strict Score: ${doc.strict_score || 0}
Embedding Score: ${doc.embedding_score || 0}
Matched Animal Terms: ${Array.isArray(doc.matched_terms) ? doc.matched_terms.join(", ") : doc.matched_terms || ""}
Matched Agencies: ${Array.isArray(doc.matched_agencies) ? doc.matched_agencies.join(", ") : doc.matched_agencies || ""}
Matched Policy Terms: ${Array.isArray(doc.matched_policy_terms) ? doc.matched_policy_terms.join(", ") : doc.matched_policy_terms || ""}

Required output format:
Relevance Status: RELEVANT or NOT_RELEVANT
Email Decision: SEND or DO_NOT_SEND
Type of Action: Proposed Rule / Final Rule / Notice / Public Comment / Permit / Hearing / Other
Urgency: High / Medium / Low
Advocacy Relevance: High / Medium / Low
Deadline Sensitivity: High / Medium / Low / None
Summary: [2-3 plain English sentences]
Why It Matters: [1-2 sentences for animal advocates]
Actionability Assessment: [state whether action is possible, informational only]
Recommended Action: Public comment / Monitor / No action available / Research further
Suggested Advocacy Talking Points: [2-3 short semicolon-separated talking points]
Deadline: YYYY-MM-DD or None
Verification Instructions: Open the official Federal Register source link, confirm the agency, publication date, document number, comment deadline, and action type before taking any advocacy action.
Disclaimer: This represents informational guidance only and not legal advice.`;

  return {
    json: {
      ...doc,
      relevance_request_body: {
        model: context.relevance_model || "openai/gpt-4o-mini",
        messages: [
          {
            role: "system",
            content: "You are a strict Federal Register classifier for animal advocacy relevance. If relevance is unclear, return NOT_RELEVANT and DO_NOT_SEND. Never invent deadlines or claims."
          },
          {
            role: "user",
            content: prompt
          }
        ],
        temperature: 0,
        max_tokens: 900
      }
    }
  };
});

function getField(content, label) {
  const regex = new RegExp(`^${label}:\\s*(.*)$`, "im");
  const match = String(content || "").match(regex);
  return match ? match[1].trim() : "";
}

const output = [];

for (const item of $input.all()) {
  const doc = item.json || {};

  let content = "";
  try {
    content = doc.choices?.[0]?.message?.content || "";
  } catch (error) {
    content = "";
  }

  content = String(content)
    .replace(/\*\*/g, "")
    .replace(/\*/g, "")
    .replace(/#{1,6}\s/g, "")
    .trim();

  if (!content || doc.error) {
    output.push({
      json: {
        ...doc,
        ai_relevance_status: "NOT_RELEVANT",
        ai_decision: "DO_NOT_SEND",
        ai_content: content
      }
    });
    continue;
  }

  const relevanceStatus = getField(content, "Relevance Status").toUpperCase();
  const emailDecisionRaw = getField(content, "Email Decision").toUpperCase();
  const advocacyRelevance = getField(content, "Advocacy Relevance");
  const summary = getField(content, "Summary");

  const parsed = {
    ai_relevance_status: relevanceStatus || "UNKNOWN",
    ai_decision: relevanceStatus === "RELEVANT" && emailDecisionRaw === "SEND" ? "SEND" : "DO_NOT_SEND",
    type_of_action: getField(content, "Type of Action"),
    urgency: getField(content, "Urgency"),
    advocacy_relevance: advocacyRelevance,
    deadline_sensitivity: getField(content, "Deadline Sensitivity"),
    ai_summary: summary,
    why_it_matters: getField(content, "Why It Matters"),
    actionability: getField(content, "Actionability Assessment"),
    recommended_action: getField(content, "Recommended Action"),
    talking_points: getField(content, "Suggested Advocacy Talking Points"),
    deadline: getField(content, "Deadline"),
    verification_instructions: getField(content, "Verification Instructions") || "Open the official Federal Register source link, confirm the agency, publication date, document number, comment deadline, and action type before taking any advocacy action.",
    disclaimer: getField(content, "Disclaimer") || "This represents informational guidance only and not legal advice.",
    ai_content: content
  };

  output.push({
    json: {
      ...doc,
      ...parsed
    }
  });
}

return output;
